const fr=(s)=>`<span class="french frhint">${s}</span>`;
const say=(txt)=>{if(!('speechSynthesis'in window)){alert('Audio unavailable in this browser. Try Chrome.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(txt);const lang=$('accent').value;u.lang=lang;u.rate=.86;const voices=speechSynthesis.getVoices().filter(v=>v.lang?.toLowerCase().startsWith(lang.toLowerCase()));if(voices.length)u.voice=voices.find(v=>v.localService)||voices[0];speechSynthesis.speak(u)};
const listen=(t,label='▶ Listen')=>`<button class="listen" data-say="${esc(t)}">${label}</button>`;
const mark=(label='✓ Mark this stage complete')=>`<button class="tick" data-mark="${sections[current][0]}">${label}</button>`;
const intro=(num,mins,label,title,lead)=>`<div class="sectionTag">${num} · ${mins} MIN · ${label}</div><h2>${title}</h2><p class="lead">${lead}</p>`;
const listQ=[];
function addQuiz(id,type,prompt,options,answer,hint,why,extra={}){listQ.push({id,type,prompt,options,answer,hint,why,...extra});}
