const modQs=[
['mod1','You _____ wear comfortable shoes for a long archaeological visit.',['must to','should','could to'],1,'Advice: should + verb.','should wear = advice.'],
['mod2','_____ you recommend a quieter excursion?',['Do could','Should you to','Could'],2,'Polite request: Could you…?','Could you recommend…?'],
['mod3','We _____ take a smaller boat if the weather is suitable.',['could','should to','can to'],0,'Possibility: could + base verb.','could take = an option.'],
['mod4','Visitors _____ follow the guide’s safety instructions.',['must to','must','musting'],1,'Obligation: must + base verb.','must follow.'],
['mod5','You _____ enter a restricted area without permission.',['mustn’t','should','can'],0,'Prohibition, not a recommendation.','mustn’t = prohibition.'],
['mod6','You _____ book ahead; it may be busy.',['should to','shoulding','should'],2,'No “to” after should.','should book.'],
['mod7','If you prefer history, you _____ enjoy Luxor.',['might','must to','shoulding'],0,'Uncertain possibility.','might enjoy expresses possibility.'],
['mod8','Which is the most polite request?',['Tell me where the station is.','Could you tell me where the station is?','Where the station is?'],1,'Could you tell me…? + statement word order.','Could you tell me where the station is?']
];modQs.forEach(x=>addQuiz(x[0],'choice',x[1],x[2],x[3],x[4],x[5]));
