function quizHtml(id){const q=listQ.find(x=>x.id===id);if(!q)return '';return `<div class="quizItem" data-quiz="${id}"><h4>${esc(q.prompt)}</h4>${q.audio?listen(q.audio,'▶ Play the recording'):''}<div class="choices">${q.options.map((o,i)=>`<button data-choice="${i}" aria-label="Choice ${i+1}: ${esc(o)}">${'ABC'[i]}. ${esc(o)}</button>`).join('')}</div><button class="hintBtn" data-hint="${id}">💡 Hint · Indice</button><div class="feedback" id="fb-${id}" role="status"></div></div>`}
function blankHtml(b){return `<div class="quizItem" data-blank="${b.id}"><h4>${esc(b.prompt)}</h4><input autocomplete="off" aria-label="Your answer" placeholder="Type your answer here…" value="${esc(state.answers[b.id]?.input||'')}"><div class="buttonrow"><button class="secondary" data-checkblank="${b.id}">✓ Check my answer</button><button class="hintBtn" data-blankhint="${b.id}">💡 Hint</button></div><div class="feedback" id="fb-${b.id}"></div></div>`}
function wordHtml(w){return `<div class="quizItem" data-word="${w.id}"><h4>${esc(w.prompt)}</h4><p class="small">Tap a word to build the sentence. Tap a selected word to return it. Check your answer.</p><div class="selectedwords" aria-label="Your sentence"></div><div class="wordbank" aria-label="Word bank"></div><div class="buttonrow"><button class="secondary" data-checkword="${w.id}">✓ Check my answer</button><button class="hintBtn" data-wordhint="${w.id}">💡 Hint</button><button class="secondary" data-wordreset="${w.id}">↻ Try again</button></div><div class="feedback" id="fb-${w.id}"></div></div>`}
