function shell(){return sections.map((s,i)=>`<button data-go="${i}" class="${i===current?'active ':''}${state.done[s[0]]?'done':''}">${s[1]}</button>`).join('')}
function welcome(){return intro('01','8','WARM-UP & RECONNECT','Where are you going next?','Begin with what you already know. Your experiences are the subject of today’s English lesson.')+`<div class="callout"><b>Your travel story</b><p>You are planning a return visit to Egypt with your husband and a trip to Norway to discover fjords. Travel plans can change, so describe possible activities with <b>might</b> and <b>could</b> until the itinerary is confirmed.</p></div><div class="taskguide"><b>Say it → extend it → ask a question.</b><p>1. <i>I'm going back to Egypt.</i> 2. <i>I'm going back to Egypt with my husband to explore some new places.</i> 3. <i>What would you recommend visiting?</i></p>${listen("I'm going back to Egypt with my husband, and I'd also like to discover the Norwegian fjords.")}</div><h3>Today's learning objectives</h3><div class="checklist"><label>✓ Describe and compare landscapes and cultural sites</label><label>✓ Ask polite questions and make suggestions</label><label>✓ Understand a short travel notice and an announcement</label><label>✓ Speak for 45–90 seconds, then write a structured message</label><label>✓ Complete an independent BRIGHT-style practice</label></div>${quizHtml('warm1')}${quizHtml('warm2')}${quizHtml('warm3')}<div class="speakingQuestion"><b>Speaking warm-up · Tell your trainer</b><p>Which part of Norway are you most curious about? What would you like to discover in Egypt this time?</p><details class="detailbox"><summary>View an A2+ model</summary><p>I would like to see the fjords in Norway. I think the scenery is beautiful. In Egypt, I want to visit new places with my husband.</p></details><details class="detailbox"><summary>View a B1 model</summary><p>I'm particularly interested in Norway's fjords because the dramatic landscape is very different from what I'm used to. When I return to Egypt with my husband, I'd like to explore places we haven't visited before, especially historical sites.</p></details></div>${mark()}`}
addQuiz('link1','choice','Choose the natural sentence: “I want to visit Luxor _____ its temples.”',['because','because of','although'],1,'A noun phrase follows this expression.','Because of + noun phrase; because + subject + verb.');
addQuiz('link2','choice','Choose the clearest contrast: “Norway is known for its fjords, _____ Egypt has outstanding ancient monuments.”',['therefore','whereas','because of'],1,'You need a contrasting link.','Whereas links two contrasting ideas.');
addQuiz('link3','choice','Which gives a nuanced reason?',['I like Egypt.','Egypt good history.','I’m especially drawn to Luxor because of its exceptionally rich heritage.'],2,'Look for an accurate personal reason and specific vocabulary.','A precise reason and natural collocation make the meaning clearer.');
addQuiz('source1','choice','An official tourism page recommends an attraction as a “must-see”. What does it mean?',['It is legally compulsory.','The publisher strongly recommends it.','Tickets are included in every trip.'],1,'Tourism language is often promotional.','Must-see means highly recommended, not mandatory.');
